// Check if today is a weekday (Monday-Friday) in US Market Time (America/New_York)
const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const dayOfWeek = today.getDay();

const inputItems = $input.all();

if (!inputItems || inputItems.length === 0) {
  console.log('⚠️ No input items received');
  return [];
}

if (dayOfWeek >= 1 && dayOfWeek <= 5) {
  console.log(`✅ Weekday detected (day ${dayOfWeek}), continuing execution`);
  return inputItems;
} else {
  console.log(`⏸️ Weekend detected (day ${dayOfWeek}), stopping execution`);
  return [];
}

const industries = {
  Technology: {
    dayIndex: 0,
    keywords: ["tech", "software", "semiconductor", "cloud", "AI", "computer", "internet", "digital", "cyber", "data", "app", "saas", "platform", "chipmaker", "electronics"]
  },
  Healthcare: {
    dayIndex: 1,
    keywords: ["health", "pharma", "biotech", "medical", "hospital", "drug", "therapeutics", "clinical", "medicine", "healthcare", "diagnostic", "vaccine", "biopharma", "life sciences"]
  },
  Finance: {
    dayIndex: 2,
    keywords: ["bank", "financial", "finance", "investment", "insurance", "credit", "lending", "mortgage", "capital", "fund", "securities", "trust", "asset management", "fintech"]
  },
  Energy: {
    dayIndex: 3,
    keywords: ["energy", "oil", "gas", "renewable", "solar", "wind", "electric", "utility", "petroleum", "power", "coal", "natural gas", "clean energy", "nuclear", "battery"]
  },
  ConsumerGoods: {
    dayIndex: 4,
    keywords: ["consumer", "retail", "goods", "product", "brand", "apparel", "fashion", "food", "beverage", "restaurant", "grocery", "merchandise", "ecommerce", "shopping"]
  },
  Industrials: {
    dayIndex: 5,
    keywords: ["industrial", "manufacturing", "machinery", "equipment", "aerospace", "defense", "transportation", "logistics", "shipping", "freight", "automotive", "parts", "supply"]
  }
};

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const dayOfWeek = now.getDay();
const adjustedDay = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

let selectedIndustry = null;
let selectedKeywords = [];
let tomorrowIndustry = null;

const industryList = Object.keys(industries);

for (const [name, config] of Object.entries(industries)) {
  if (config.dayIndex === adjustedDay) {
    selectedIndustry = name;
    selectedKeywords = config.keywords;
    const tomorrowIndex = (adjustedDay + 1) % industryList.length;
    for (const [tomorrowName, tomorrowConfig] of Object.entries(industries)) {
      if (tomorrowConfig.dayIndex === tomorrowIndex) {
        tomorrowIndustry = tomorrowName;
        break;
      }
    }
    break;
  }
}

if (!selectedIndustry) {
  selectedIndustry = "Technology";
  selectedKeywords = industries.Technology.keywords;
  tomorrowIndustry = "Healthcare";
}

const dayNames = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
console.log(`📅 Today is ${dayNames[adjustedDay]}`);
console.log(`✅ Selected Industry: ${selectedIndustry}`);
console.log(`📆 Tomorrow's Industry: ${tomorrowIndustry}`);

return [{
  json: {
    industry: selectedIndustry,
    industryKeywords: selectedKeywords,
    tomorrowIndustry: tomorrowIndustry,
    dayOfWeek: dayNames[adjustedDay],
    allIndustries: industryList
  }
}];

const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
let tradingDate = new Date(today);
const dayOfWeek = tradingDate.getDay();

if (dayOfWeek === 0) {
  tradingDate.setDate(tradingDate.getDate() - 2);
} else if (dayOfWeek === 6) {
  tradingDate.setDate(tradingDate.getDate() - 1);
}

const year = tradingDate.getFullYear();
const month = String(tradingDate.getMonth() + 1).padStart(2, '0');
const day = String(tradingDate.getDate()).padStart(2, '0');
const dateStr = `${year}-${month}-${day}`;

console.log(`📅 Trading date: ${dateStr}`);

return [{ json: { tradingDate: dateStr } }];

// Parse each stock snapshot from Polygon API + merge with grouped daily metadata
const inputItem = $input.item.json;
const idx = $itemIndex;
const baseItems = $('Filter by Industry').all();
const baseStock = baseItems[idx]?.json || {};
const industry = $('Set Industry Filter').first().json.industry || 'Technology';

const tickerObj = inputItem.ticker || {};
const todayBar = (tickerObj.day && tickerObj.day.c > 0) ? tickerObj.day : baseStock;
const prevDayBar = tickerObj.prevDay || {};

const symbol = tickerObj.ticker || baseStock.symbol || 'UNKNOWN';
const currentPrice = todayBar.c || baseStock.close || 0;
const openPrice = todayBar.o || baseStock.open || currentPrice;
const highPrice = todayBar.h || baseStock.high || currentPrice * 1.01;
const lowPrice = todayBar.l || baseStock.low || currentPrice * 0.99;
const vwap = todayBar.vw || baseStock.vwap || ((highPrice + lowPrice + currentPrice) / 3);
const previousClose = prevDayBar.c || baseStock.prevClose || openPrice;
const volume = todayBar.v || baseStock.volume || 0;
const prevVolume = prevDayBar.v || (volume * 0.72) || 1;

const change = previousClose > 0
  ? ((currentPrice - previousClose) / previousClose) * 100
  : (baseStock.change || 0);

const rvolRaw = prevVolume > 0 ? (volume / prevVolume) : 1.45;
const rvol = Math.min(5.5, Math.max(1.15, rvolRaw));
const vwapDeltaPct = vwap > 0 ? ((currentPrice - vwap) / vwap) * 100 : 0;
const dayRange = Math.max(0.01, highPrice - lowPrice);
const dayRangePct = Math.min(100, Math.max(0, ((currentPrice - lowPrice) / dayRange) * 100));

return {
  symbol: symbol,
  name: baseStock.name || symbol,
  companyName: baseStock.companyName || symbol,
  subSector: baseStock.subSector || `${industry} Sector`,
  price: currentPrice,
  change: change,
  volume: volume,
  prevVolume: prevVolume,
  rvol: Number(rvol.toFixed(2)),
  dollarVolume: currentPrice * volume,
  open: openPrice,
  high: highPrice,
  low: lowPrice,
  vwap: vwap,
  vwapDeltaPct: Number(vwapDeltaPct.toFixed(2)),
  dayRangePct: Math.round(dayRangePct),
  prevClose: previousClose,
  industry: industry,
  timestamp: todayBar.t || Date.now()
};

const allItems = $input.all();
const originalStocks = $('Parse Snapshot Data').all();

function extractJSON(text) {
  if (!text) return null;
  text = String(text).replace(/```json\n?/g, '').replace(/```\n?/g, '');
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      return JSON.parse(jsonMatch[0]);
    } catch (e) {
      return null;
    }
  }
  return null;
}

const validatedAnalyses = allItems.map((item, index) => {
  const aiOutput = item.json.output || [];
  const originalStock = originalStocks[index]?.json || {};

  // Support both LangChain nested content[0].text and flat output_text
  let textContent = '';
  if (Array.isArray(aiOutput) && aiOutput[0]?.content?.[0]?.text) {
    textContent = aiOutput[0].content[0].text;
  } else if (Array.isArray(aiOutput)) {
    textContent = aiOutput.find(o => o.type === 'output_text')?.text || '';
  } else if (item.json.text) {
    textContent = item.json.text;
  }

  const analysis = extractJSON(textContent) || {};
  const price = Number(originalStock.price) || 100;
  const open = Number(originalStock.open) || price;
  const high = Math.max(price, Number(originalStock.high) || price * 1.012);
  const low = Math.min(price, Number(originalStock.low) || price * 0.988);
  const vwap = Number(originalStock.vwap) || ((high + low + price) / 3);
  const change = Number(originalStock.change) || 0;
  const rvol = Number(originalStock.rvol) || 1.4;
  const volM = ((originalStock.volume || 0) / 1000000).toFixed(1);

  let action = analysis.action;
  if (!['Buy', 'Hold', 'Sell'].includes(action)) {
    if (change >= 1.0 || (price > vwap && change > 0.3)) action = 'Buy';
    else if (change <= -0.5 || price < vwap * 0.996) action = 'Sell';
    else action = 'Hold';
  }

  // Deterministic Institutional Trade Plan (Entry, Target, Stop-Loss, R:R)
  const intradayRange = Math.max(high - low, price * 0.015);
  let setupBadge, entryLow, entryHigh, stopPrice, targetPrice, rrRatio, entryNote, targetNote, stopNote;

  if (action === 'Sell') {
    setupBadge = '▼ VWAP BREAKDOWN SHORT';
    entryLow = price * 0.998;
    entryHigh = Math.max(price * 1.002, vwap);
    stopPrice = Math.max(high * 1.002, price + intradayRange * 0.65);
    const risk = Math.max(price * 0.008, stopPrice - price);
    targetPrice = price - risk * 2.5;
    rrRatio = '1 : 2.5';
    entryNote = 'Short rejection below VWAP';
    targetNote = 'Next institutional demand zone';
    stopNote = 'Above intraday VWAP resistance';
  } else if (action === 'Buy') {
    setupBadge = originalStock.dayRangePct >= 70 ? '▲ HOD BREAKOUT LONG' : '▲ VWAP RECLAIM LONG';
    entryLow = Math.min(price * 0.997, (price + vwap) / 2);
    entryHigh = price * 1.002;
    stopPrice = Math.min(vwap * 0.995, price - intradayRange * 0.60);
    const risk = Math.max(price * 0.008, price - stopPrice);
    targetPrice = price + risk * 2.7;
    rrRatio = '1 : 2.7';
    entryNote = 'Confirm hold above VWAP / HOD';
    targetNote = 'Next institutional supply zone';
    stopNote = 'Below intraday VWAP support';
  } else {
    setupBadge = '◆ VWAP BREAKOUT WATCH';
    entryLow = price;
    entryHigh = high * 1.001;
    stopPrice = Math.min(vwap * 0.994, low * 0.998);
    const risk = Math.max(price * 0.008, price - stopPrice);
    targetPrice = price + risk * 2.4;
    rrRatio = '1 : 2.4';
    entryNote = 'Trigger on high-volume HOD break';
    targetNote = 'Measured range expansion target';
    stopNote = 'Below intraday VWAP support';
  }

  const targetPct = ((targetPrice - price) / price) * 100;
  const stopPct = ((stopPrice - price) / price) * 100;

  // Build 10 realistic intraday candlesticks anchored to actual Open -> Low -> VWAP -> High -> Close
  const span = Math.max(0.01, high - low);
  const norm = v => Math.min(0.96, Math.max(0.04, (v - low) / span));
  const oN = norm(open);
  const cN = norm(price);
  const vN = norm(vwap);
  const hN = 0.95;
  const lN = 0.06;

  // Smooth 10-step intraday curve keyed off intraday Close vs Open (cN >= oN)
  const waypoints = cN >= oN
    ? [oN, Math.max(lN, oN - 0.10), lN + 0.04, (lN + vN) / 2, vN - 0.03, vN + 0.04, (vN + cN) / 2, Math.min(hN, cN + 0.05), Math.max(vN, cN - 0.05), hN - 0.03, cN]
    : [oN, Math.min(hN, oN + 0.10), hN - 0.04, (hN + vN) / 2, vN + 0.03, vN - 0.04, (vN + cN) / 2, Math.max(lN, cN - 0.05), Math.min(vN, cN + 0.05), lN + 0.04, cN];

  const candles = [];
  for (let i = 0; i < 10; i++) {
    const co = waypoints[i];
    const cc = waypoints[i + 1];
    const ch = Math.min(0.98, Math.max(co, cc) + 0.05 + ((i % 3) * 0.015));
    const cl = Math.max(0.02, Math.min(co, cc) - 0.05 - (((i + 1) % 3) * 0.015));
    const cv = Math.min(1.0, 0.35 + (Math.abs(cc - co) * 2.2) + (i >= 7 ? 0.25 : 0));
    candles.push({ o: Number(co.toFixed(3)), h: Number(ch.toFixed(3)), l: Number(cl.toFixed(3)), c: Number(cc.toFixed(3)), v: Number(cv.toFixed(2)) });
  }

  const defaultDesk1 = `${originalStock.symbol} ${price >= vwap ? 'reclaimed' : 'testing'} $${vwap.toFixed(2)} VWAP on ${volM}M vol—`;
  const defaultDesk2 = `watching $${entryHigh.toFixed(2)} trigger toward $${targetPrice.toFixed(2)}.`;

  const rationale = analysis.rationale || `${price >= vwap ? 'Institutional accumulation above' : 'Active flow near'} $${vwap.toFixed(2)} VWAP (${rvol.toFixed(1)}x RVOL)`;

  return {
    ticker: originalStock.symbol,
    symbol: originalStock.symbol,
    companyName: originalStock.companyName || originalStock.symbol,
    name: originalStock.companyName || originalStock.symbol,
    subSector: originalStock.subSector || `${originalStock.industry} Sector`,
    description: `${originalStock.companyName} • ${originalStock.subSector || originalStock.industry}`,
    price: price,
    lastTradePrice: price,
    open: open,
    high: high,
    low: low,
    vwap: vwap,
    vwapDeltaPct: originalStock.vwapDeltaPct || 0,
    dayRangePct: originalStock.dayRangePct || 50,
    change: change,
    volume: originalStock.volume || 0,
    rvol: rvol,
    dollarVolume: originalStock.dollarVolume || (price * (originalStock.volume || 0)),
    industry: originalStock.industry,
    action: action,
    setupBadge: setupBadge,
    confidence: analysis.confidence || 'High',
    confidenceScore: 0.9,
    rationale: rationale,
    reasoning: rationale,
    deskNote1: (analysis.deskNote1 || defaultDesk1).slice(0, 48),
    deskNote2: (analysis.deskNote2 || defaultDesk2).slice(0, 48),
    entryLow: Number(entryLow.toFixed(2)),
    entryHigh: Number(entryHigh.toFixed(2)),
    entryDisplay: `$${entryLow.toFixed(2)} – $${entryHigh.toFixed(2)}`,
    targetPrice: Number(targetPrice.toFixed(2)),
    targetPct: Number(targetPct.toFixed(1)),
    targetDisplay: `$${targetPrice.toFixed(2)} (${targetPct >= 0 ? '+' : ''}${targetPct.toFixed(1)}%)`,
    stopPrice: Number(stopPrice.toFixed(2)),
    stopPct: Number(stopPct.toFixed(1)),
    stopDisplay: `$${stopPrice.toFixed(2)} (${stopPct >= 0 ? '+' : ''}${stopPct.toFixed(1)}%)`,
    rrRatio: rrRatio,
    entryNote,
    targetNote,
    stopNote,
    candles
  };
});

return validatedAnalyses.map(a => ({ json: a }));

const items = $input.all();
const predictions = items.map(item => item.json);

predictions.forEach(stock => {
  const absChange = Math.max(0.4, Math.abs(stock.change || 0));
  const dollarVol = (stock.price || 10) * (stock.volume || 0);
  // Rank by institutional flow + percentage movement
  stock.momentum = absChange * Math.sqrt(dollarVol) * (stock.rvol || 1.2);
});

predictions.sort((a, b) => b.momentum - a.momentum);

const buys = predictions.filter(p => p.action === 'Buy');
const holds = predictions.filter(p => p.action === 'Hold');
const sells = predictions.filter(p => p.action === 'Sell');

return [{
  json: {
    buys,
    holds,
    sells,
    allPredictions: predictions,
    top5Hottest: predictions.slice(0, 5),
    summary: {
      totalAnalyzed: predictions.length,
      buyCount: buys.length,
      holdCount: holds.length,
      sellCount: sells.length
    }
  }
}];

// Select Top 4 High-Conviction Institutional Setups for the 60s Trader Terminal Video
const parsedData = $input.first().json;
const buys = parsedData.buys || [];
const holds = parsedData.holds || [];
const sells = parsedData.sells || [];
const allPredictions = parsedData.allPredictions || [...buys, ...holds, ...sells];

// Pick up to 3 top Breakout Longs + 1 Tactical Short/Pullback (or top 4 overall by institutional momentum)
const selectedSetups = [];
const topBuys = buys.slice(0, 3);
selectedSetups.push(...topBuys);

if (sells.length > 0 && selectedSetups.length < 4) {
  selectedSetups.push(sells[0]);
}

for (const s of allPredictions) {
  if (selectedSetups.length >= 4) break;
  if (!selectedSetups.some(x => x.symbol === s.symbol)) {
    selectedSetups.push(s);
  }
}

const videoStocks = {
  buys: selectedSetups.filter(s => s.action === 'Buy'),
  holds: selectedSetups.filter(s => s.action === 'Hold'),
  sells: selectedSetups.filter(s => s.action === 'Sell'),
  setups: selectedSetups
};

return [{
  json: {
    videoSetups: selectedSetups,
    videoStocks: videoStocks,
    allStocks: allPredictions,
    summary: {
      totalAnalyzed: allPredictions.length,
      totalSelected: selectedSetups.length,
      buyCount: videoStocks.buys.length,
      holdCount: videoStocks.holds.length,
      sellCount: videoStocks.sells.length
    }
  }
}];

