const item = $input.first();
const industry = $('Set Industry Filter').first().json.industry || 'Technology';
const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const newFilename = `audio_AIStockAdvisor_${industry}_${dateStr}.mp3`;

console.log(`🎵 Renaming audio file to: ${newFilename}`);

const binaryData = item.binary;
const newItem = {
  json: item.json,
  binary: {}
};

for (const key in binaryData) {
  newItem.binary[key] = {
    ...binaryData[key],
    fileName: newFilename
  };
}

return [newItem];

const uploadData = $('Upload Audio to Drive').first().json;
const renameNode = $('Rename Audio File').first();
const fileId = uploadData.id;
const fileName = uploadData.name;
const publicUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;

// ElevenLabs mp3_44100_128 is strictly 128 kbps CBR = 16,000 bytes per second
const byteSize = parseInt(uploadData.size, 10) || renameNode?.binary?.data?.bytes || 860000;
const exactAudioDuration = Number((byteSize / 16000).toFixed(2));

return [{
  json: {
    fileId: fileId,
    fileName: fileName,
    publicUrl: publicUrl,
    downloadUrl: publicUrl,
    byteSize: byteSize,
    audioDuration: exactAudioDuration
  }
}];

// Institutional Dark Terminal (TradingView / Bloomberg Style) + Exact Phonetic Audio Sync
const audioData = $('Get Audio URL').first().json;
const stocksNodeData = $('🎯 Select Video Stocks (10 Total)').first().json;
const industryData = $('Set Industry Filter').first().json;
const scriptNode = $('Generate Video Script - OpenAI').first().json;

const audioUrl = audioData.publicUrl || '';
const exactAudioDur = Number(audioData.audioDuration) || 52.0;
const industry = industryData.industry || 'Technology';
const setups = (stocksNodeData.videoSetups || []).slice(0, 4);

if (setups.length === 0) {
  throw new Error('No setups available for video generation.');
}

// Extract spoken script text to calculate exact per-paragraph timing
let rawScript = '';
if (Array.isArray(scriptNode.output) && scriptNode.output[0]?.content?.[0]?.text) {
  rawScript = scriptNode.output[0].content[0].text;
} else if (Array.isArray(scriptNode.output)) {
  rawScript = scriptNode.output.find(o => o.type === 'output_text')?.text || '';
}

const paragraphs = rawScript
  .split(/\n\s*\n/)
  .map(p => p.trim())
  .filter(Boolean);

// Phonetic length estimator: accounts for spoken expansion of numbers, $, %, and decimals
function phoneticWeight(str) {
  if (!str) return 40;
  let expanded = str
    .replace(/\$/g, ' dollars ')
    .replace(/%/g, ' percent ')
    .replace(/\./g, ' point ')
    .replace(/[0-9]/g, ' digit ');
  return expanded.length + 18; // +18 for natural inter-paragraph breath pause (~0.42s)
}

const segCount = setups.length + 2; // Intro + N setups + Outro
const weights = [];
if (paragraphs.length >= segCount) {
  weights.push(phoneticWeight(paragraphs[0]));
  for (let i = 0; i < setups.length; i++) {
    weights.push(phoneticWeight(paragraphs[i + 1]));
  }
  weights.push(phoneticWeight(paragraphs.slice(setups.length + 1).join(' ')));
} else {
  // Fallback proportional weights if LLM merged paragraphs
  weights.push(85);
  for (let i = 0; i < setups.length; i++) weights.push(190);
  weights.push(75);
}

const totalWeight = weights.reduce((a, b) => a + b, 0);
const totalDuration = Number((exactAudioDur + 0.6).toFixed(2));

const segTimes = [];
let cumTime = 0;
for (let i = 0; i < weights.length; i++) {
  const dur = Number(((weights[i] / totalWeight) * exactAudioDur).toFixed(2));
  segTimes.push({ start: Number(cumTime.toFixed(2)), duration: dur });
  cumTime += dur;
}
// Extend final outro segment to cover the 0.6s tail buffer
segTimes[segTimes.length - 1].duration = Number((totalDuration - segTimes[segTimes.length - 1].start).toFixed(2));

const RECT = 'M 0 0 L 100 0 L 100 100 L 0 100 L 0 0 Z';
const F = 'Inter';
const C = {
  bg: '#090D16',
  card: '#111827',
  chartBg: '#0D131F',
  border: '#334155',
  grid: 'rgba(148, 163, 184, 0.08)',
  white: '#FFFFFF',
  slate: '#94A3B8',
  lightSlate: '#E2E8F0',
  emerald: '#10B981',
  emeraldBright: '#34D399',
  emeraldBg: 'rgba(6, 78, 59, 0.85)',
  cyan: '#38BDF8',
  cyanBg: 'rgba(12, 74, 110, 0.85)',
  amber: '#FACC15',
  amberBg: 'rgba(66, 32, 6, 0.90)',
  rose: '#FB7185',
  roseBright: '#F43F5E',
  roseBg: 'rgba(76, 18, 36, 0.85)'
};

const todayStr = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase();
const els = [];

// 1. Base Institutional Dark Canvas
els.push({
  type: 'shape', path: RECT, x: '50%', y: '50%', width: '100%', height: '100%',
  fill_color: C.bg, time: 0, duration: totalDuration
});

// Subtle Terminal Grid
for (let i = 1; i < 24; i++) {
  els.push({
    type: 'shape', path: RECT, x: '50%', y: (i * 80) + 'px', width: '1080px', height: '1px',
    fill_color: C.grid, time: 0, duration: totalDuration
  });
}
for (let i = 1; i < 12; i++) {
  els.push({
    type: 'shape', path: RECT, x: (i * 90) + 'px', y: '50%', width: '1px', height: '1920px',
    fill_color: C.grid, time: 0, duration: totalDuration
  });
}

// ==================== INTRO SCREEN ====================
const introT = segTimes[0];
const hookSummary = paragraphs[0] || `Institutional flow scanner detected ${setups.length} high-conviction VWAP & unusual volume setups today.`;

els.push({
  type: 'shape', path: RECT, x: '540px', y: '920px', width: '960px', height: '980px',
  fill_color: C.card, stroke_color: C.border, stroke_width: '2px', border_radius: '32px',
  time: introT.start, duration: introT.duration, animations: [{ type: 'fade', duration: 0.25 }]
});

els.push({
  type: 'shape', path: RECT, x: '540px', y: '540px', width: '460px', height: '64px',
  fill_color: C.emeraldBg, stroke_color: C.emerald, stroke_width: '2px', border_radius: '16px',
  time: introT.start, duration: introT.duration
});
