const item = $input.item.json;
let responseText = '';
if (Array.isArray(item.output) && item.output[0]?.content?.[0]?.text) {
  responseText = item.output[0].content[0].text;
} else if (item.response?.text) {
  responseText = item.response.text;
}

const setups = $('🎯 Select Video Stocks (10 Total)').first().json.videoSetups || [];
const topTickers = setups.map(s => `$${s.symbol}`).join(', ');

let parsed;
try {
  const clean = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  const m = clean.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : clean);
  if (!parsed.caption || !parsed.hashtags) throw new Error('Missing fields');
} catch (error) {
  parsed = {
    caption: `🚨 Institutional VWAP & Volume Setups: ${topTickers} (Exact Entry, Target & Stop Levels) 📊`,
    hashtags: '#StockMarket #DayTrading #SwingTrading #TradingView #StocksToWatch #OptionsTrading #TechnicalAnalysis #AIStocks',
    thumbnailText: '🔥 TOP 4 TRADE SETUPS'
  };
}

return [{ json: parsed }];
